  const ui=root.PlatformUI,M=root.CustomerProfile,services=root.FourNodeWorkspace.profileServices(),oldPage=root.Pages['customer-directory'],layerId='customer-profile-detail';
  const esc=value=>ui.escape(String(value??'')),clone=value=>value===undefined?undefined:JSON.parse(JSON.stringify(value));
  const labels={BUSINESS:'统一业务',AI:'AI原记录',CLOUD:'云呼叫记录',DCC:'预外呼任务记录'};
  const followupStates={COMPLETE:'已归档',WAITING_CONTENT:'待填写',WAITING_FACTS:'待结果',WAITING_REVIEW:'待核对',ABANDONED:'废弃保留（未正常完成）',ACTIVE:'办理中',ENDED:'已结束',RUNNING:'执行中',QUEUED:'排队中',accepted:'已受理',running:'执行中',queued:'排队中',retry:'待重呼',unknown:'状态待核',ended:'执行已结束'};
  const followupState=value=>followupStates[value]||(typeof value==='string'&&/[\u3400-\u9fff]/.test(value)?value:'状态待核');
  let scope='',keyword='',sourceFilter='',page=1,customerId='',generation=0,aiLoading=false,aiFailure=null;
  const context=()=>services.context(),stable=value=>JSON.stringify(value,(_,item)=>item&&typeof item==='object'&&!Array.isArray(item)?Object.fromEntries(Object.keys(item).sort().map(key=>[key,item[key]])):item),scopeMetadata=c=>({kind:c?.scope?.kind,enterpriseId:c?.scope?.tenant?.enterpriseId,brandId:c?.scope?.tenant?.brandId,enabled:c?.scope?.tenant?.enabled}),scopeKey=()=>{const active=root.parent?.DSession?.context?.();return stable({native:context(),account:active?.account?.id||'',scope:active?.scope?.id||'',grant:active?.scope?.grant||null,tenant:scopeMetadata(active)});},host=()=>root.parent?.DModuleHost;
  const arg=value=>esc(JSON.stringify(value)),action=(label,name,args=[],primary=false)=>'<button type="button" class="btn'+(primary?' btn-primary':'')+'" onclick="CustomerProfiles.'+name+'('+args.map(arg).join(',')+')">'+esc(label)+'</button>';
  const sourceKey=ref=>JSON.stringify(ref||{});
  function currentPage(){const parent=root.parent?.DApp?.currentPage?.();if(parent&&parent!=='PAGE-2203')return false;const route=root.RouteRuntime?.snapshot?.()?.key;return !route||route==='customer-directory';}
  function authorized(){const c=context(),owner=root.DNativeContext?.context,active=root.parent?.DSession?.context?.();if(owner&&(!active||owner.account?.id!==active.account?.id||owner.scope?.id!==active.scope?.id||stable(owner.scope?.grant||null)!==stable(active.scope?.grant||null)||stable(scopeMetadata(owner))!==stable(scopeMetadata(active))))return false;return c.valid===true&&(!root.parent?.DSession?.allowed||root.parent.DSession.allowed('PAGE-2203')===true);}
