  function time(value,fallback='未记录'){const at=M.stamp(value);if(at===null)return fallback;if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value+'（具体时间未记录）';return new Date(at).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});}
