    return '<section class="platform-page customer-profile-page">'+ui.pageHeader('客户档案','按客户统一查看AI、预外呼、人工联系与业务跟进；各来源事实和权限分别保留。',action('刷新','reload'))+'<div class="filter-panel"><label class="field"><span>客户或业务</span><input id="customer-profile-keyword" value="'+esc(keyword)+'" placeholder="称呼、完整号码或业务编码"></label><label class="field"><span>联系来源 / 方式</span><select id="customer-profile-source">'+[['','全部'],['AI','AI外呼'],['PREDICTIVE','预外呼'],['MANUAL','人工外呼'],['BUSINESS','统一业务'],['CLOUD','原云呼叫'],['DCC','原预外呼任务']].map(([v,l])=>'<option value="'+v+'"'+(v===sourceFilter?' selected':'')+'>'+l+'</option>').join('')+'</select></label><div class="filter-actions">'+action('查询','query',[],true)+action('重置','reset')+'</div></div>'+notice(result)+'<section class="panel-card"><div class="panel-header"><h2>客户列表</h2><span>当前可见 '+rows.length+' 位客户'+(result.status==='partial'?' · 部分来源待核':'')+'</span></div><p class="field-hint">业务跟进与通话分别统计；受理、排队和待核记录不计为实际拨打，未知时长显示为未记录。</p>'+ui.table(columns,rows.slice((page-1)*10,page*10),{rowOffset:(page-1)*10,emptyText:'当前范围暂无可关联客户',emptyDetail:result.status==='partial'?'部分来源尚未可靠取得，请查看上方提示或原来源记录。':'可尝试重置筛选；尚未拨打的已导入业务也可归档查看。',footer:ui.pagination(rows.length,page,10,'CustomerProfiles.setPage')})+'</section>'+pendingTable(result)+'</section>';
